"""Report imported names never referenced in the same module, and top-level defs never referenced anywhere."""
import ast
import pathlib
import sys

root = pathlib.Path(sys.argv[1])
dirs = ["config", "controllers", "database", "middlewares", "models", "services", "utils", "views"]
files = [root / "app.py"] + [p for d in dirs for p in (root / d).rglob("*.py")]
all_src = "\n".join(p.read_text() for p in files)
problems = 0
for path in files:
    tree = ast.parse(path.read_text())
    used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | \
           {n.value.id for n in ast.walk(tree) if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name)}
    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            for alias in node.names:
                name = (alias.asname or alias.name).split(".")[0]
                if name not in used:
                    problems += 1
                    print(f"unused import {name} in {path.relative_to(root)}")
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.ClassDef)) and not node.name.startswith("_"):
            if all_src.count(node.name) < 2:
                problems += 1
                print(f"unreferenced def {node.name} in {path.relative_to(root)}")
print("problems:", problems)

